#!/bin/bash
cd "$(dirname "$0")"
~/.local/bin/mflux-generate-z-image-turbo -q 4 --low-ram --steps 8 --width 832 --height 1216 --seed 31 --prompt "Photorealistic full-length portrait of a charismatic stylish film director in his 40s with playful swagger, mid-stride confident strut, one hand in pocket, other hand holding a sleek golden megaphone resting on his shoulder, cheeky mischievous grin and one raised eyebrow, neat short beard, slicked back dark hair, round tortoiseshell sunglasses pushed up on his head, perfectly clean tailored navy velvet blazer, crisp black turtleneck, slim charcoal trousers, polished brown leather Chelsea boots, burgundy silk pocket square, smart and elegant, full body head to toe, plain solid very dark navy studio background, gold rim light, cinematic lighting, high-end fashion editorial photography" --output max3.png >/dev/null 2>&1 && echo "made max3"
